CREATE TABLE releases(id BINARY(16) PRIMARY KEY,game_id BINARY(16) NOT NULL,version_id BINARY(16) NOT NULL,build_id BINARY(16) NOT NULL,channel VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,release_notes TEXT NOT NULL,created_by BINARY(16),approved_by BINARY(16),approved_at TIMESTAMP(6),released_at TIMESTAMP(6),rollback_of_release_id BINARY(16),created_at TIMESTAMP(6) NOT NULL,revision BIGINT NOT NULL,INDEX idx_release_game(game_id),FOREIGN KEY(rollback_of_release_id) REFERENCES releases(id));
CREATE TABLE release_decisions(id BINARY(16) PRIMARY KEY,release_id BINARY(16) NOT NULL,actor_id BINARY(16) NOT NULL,decision VARCHAR(30) NOT NULL,comment VARCHAR(1000),created_at TIMESTAMP(6) NOT NULL,INDEX idx_decision_release(release_id),FOREIGN KEY(release_id) REFERENCES releases(id) ON DELETE CASCADE);